import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
        if not isinstance(data, list) or not data:
            raise ValueError("Invalid or empty JSON data")
        for entry in data:
            if not isinstance(entry.get("Country"), str) or not isinstance(entry.get("Population"), (int, float)) or entry["Population"] < 0:
                raise ValueError("Invalid data entry")
        for entry in data:
            entry["Population"] = math.floor(entry["Population"])
        df = pd.DataFrame(data, columns=["Country", "Population"])
        file_path = os.path.join(output_dir, file_name)
        df.to_csv(file_path, index=False)
        return file_path, df
    except ValueError as ve:
        raise ve
    except IOError as ioe:
        raise ioe

